""" Merge two positions and return as a list of strings

        pos1: iterable object containing the first positions data
        pos2: iterable object containing the second positions data

        Example:
            >>> join_positions('ABCD','1234')
                ['A1', 'B2', 'C3', 'D4']
    """
def join_positions(pos1: Any, pos2: Any) -> object {
    return [''.join([r1, r2]) for (r1, r2) in zip(pos1, pos2)];
}

"""Converts variant locations in GWAS catalog format to GTEx format.

    i.e. given 'chr1_64764_C_T_b38', returns '4:79296443'.
    """
def gtex_location_to_gwas_location_(gtex_location: str) -> str {
    parts = gtex_location.split("_");
    chr = parts[0][3];
    return f"{chr}:{parts[1]}";
}

