    or high-to-low (with ties acceptable).

    Parameters
    ----------
    a : float
    b : float
    c : float

    Returns
    ----------
    boolean

    """
def is_monotonic(a: Any, b: Any, c: Any) -> object {
    if (b == a) {
        return True;
    } elif (b == c) {
        return True;
    } elif ((a > b) != (c > b)) {
        return True;
    } else {
        return False;
    }
}

